import csv
import io
import re
from typing import List, Dict, Union


_EXPECTED_WIDTH = 9


def _fallback_parse(text: str) -> List[List[str]]:
    rows: List[List[str]] = []
    row: List[str] = []
    field: List[str] = []
    in_quotes = False
    field_started = False
    i = 0
    n = len(text)

    while i < n:
        ch = text[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(ch)
            i += 1
            continue

        if ch == '"' and not field_started:
            in_quotes = True
            field_started = True
            i += 1
            continue

        if ch == ',':
            row.append("".join(field))
            field = []
            field_started = False
            i += 1
            continue

        if ch == '\r' or ch == '\n':
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            field_started = False
            if ch == '\r' and i + 1 < n and text[i + 1] == '\n':
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        field_started = True
        i += 1

    if field or row or field_started or in_quotes:
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_records(text: str) -> List[List[str]]:
    try:
        reader = csv.reader(
            io.StringIO(text, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False,
        )
        return [list(row) for row in reader]
    except (csv.Error, ValueError):
        return _fallback_parse(text)


def _is_blank(row: List[str]) -> bool:
    return not row or all(value == "" for value in row)


def _header_score(records: List[List[str]], index: int) -> float:
    row = records[index]
    width = len(row)
    score = 30.0 if width == _EXPECTED_WIDTH else -8.0 * abs(width - _EXPECTED_WIDTH)

    nonempty = 0
    header_like = 0.0
    structured = re.compile(
        r"^(?:"
        r"[=+\-@]|"
        r"\$?\d+(?:[.,]\d+)?%?|"
        r"\d{1,4}[/-]\d{1,2}[/-]\d{1,4}|"
        r"\d{1,2}:\d{2}(?::\d{2})?|"
        r"(?:https?|ftp)://"
        r")",
        re.IGNORECASE,
    )

    seen = set()
    for value in row:
        stripped = value.strip()
        if not stripped:
            continue
        nonempty += 1
        seen.add(stripped.casefold())

        if structured.match(stripped):
            header_like -= 2.5
        elif re.search(r"[A-Za-z]", stripped):
            header_like += 2.0
            if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ /().'-]*", stripped):
                header_like += 1.0
        else:
            header_like -= 0.5

    score += nonempty * 1.4
    score += header_like
    score += min(len(seen), _EXPECTED_WIDTH) * 0.3

    if index == 0 or _is_blank(records[index - 1]) or len(records[index - 1]) != _EXPECTED_WIDTH:
        score += 5.0

    checked = 0
    compatible = 0
    for following in records[index + 1:]:
        if _is_blank(following):
            continue
        checked += 1
        if len(following) == _EXPECTED_WIDTH:
            compatible += 1
        elif abs(len(following) - _EXPECTED_WIDTH) <= 1:
            compatible += 0.5
        if checked >= 8:
            break

    if checked:
        score += 8.0 * compatible / checked

    score -= min(index, 500) * 0.01
    return score


def _find_header(records: List[List[str]]) -> int:
    candidates = [i for i, row in enumerate(records) if not _is_blank(row)]
    if not candidates:
        return -1

    exact = [i for i in candidates if len(records[i]) == _EXPECTED_WIDTH]
    pool = exact if exact else candidates
    return max(pool, key=lambda i: _header_score(records, i))


def _normalize_width(row: List[str]) -> List[str]:
    values = [str(value) for value in row]

    if len(values) < _EXPECTED_WIDTH:
        return values + [""] * (_EXPECTED_WIDTH - len(values))

    if len(values) > _EXPECTED_WIDTH:
        return values[:_EXPECTED_WIDTH - 1] + [
            ",".join(values[_EXPECTED_WIDTH - 1:])
        ]

    return values


def parse_csv(raw_csv: str) -> Union[str, Dict[str, List]]:
    if not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = _read_records(raw_csv)
    header_index = _find_header(records)

    if header_index < 0:
        return {"columns": [], "rows": []}

    columns = _normalize_width(records[header_index])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows: List[List[str]] = []
    for record in records[header_index + 1:]:
        rows.append(_normalize_width(record))

    return {"columns": columns, "rows": rows}
